    /** Tüm ikonlar 56x56'lık kare alanda ortalı durur (tx/ty: eski f7 ikonlarının kayması). */
    private fun build(name: String, tx: Float, ty: Float, d: String): ImageVector =
        ImageVector.Builder(
            name = name,
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = BOX,
            viewportHeight = BOX
        ).group(
            translationX = tx,
            translationY = ty
        ) {
            addPath(
                pathData = PathParser().parsePathString(d).toNodes(),
                fill = SolidColor(Color.Black)
            )
        }.build()

    private const val BOX = 56f
}
